SELECT jsonb_build_object('id',level.id,'xxHash',level.xx_hash,'workshopId',item.workshop_id::text, 'fileUid',item.file_uid,'name',item.name,'fileAuthor',item.file_author, 'points',contribution.level_points,'records',(SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) value WHERE value.id_level=level.id)) AS value FROM public."user" account JOIN public.user_point_contribution contribution ON contribution.id_user=account.id JOIN public.level level ON level.id=contribution.id_level AND level.publicly_visible=true JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true WHERE account.discord_id=$1 AND contribution.level_position>1 AND contribution.level_points-contribution.player_decayed_points >= greatest(100,contribution.level_points*0.15) ORDER BY contribution.level_points-contribution.player_decayed_points DESC,level.id LIMIT $2
